function REBALANCE(leaves):            # leaves: list of leaf values
  level <- [ Leaf(v) for v in leaves ]
  while length(level) > 1:
    next <- []
    for i in 0, 2, 4, ... < length(level):
      if i+1 < length(level):
        next.append(Node(level[i], level[i+1]))
      else:
        next.append(level[i])           # carry odd node up
    level <- next
  return level[0]

